CREATE OR REPLACE FUNCTION evidence.is_valid_tagged_value(candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'evidence', 'pg_temp'
AS $function$
        DECLARE
            tag text;
            value_type text;
            item jsonb;
            key_count integer;
            value_text text;
        BEGIN
            IF jsonb_typeof(candidate) IS DISTINCT FROM 'object' THEN
                RETURN false;
            END IF;
            SELECT count(*) INTO key_count
              FROM jsonb_object_keys(candidate);
            tag := candidate ->> 'type';

            IF tag = 'tuple' THEN
                IF key_count <> 2
                   OR NOT candidate ?& ARRAY['type', 'items']
                   OR jsonb_typeof(candidate -> 'items') IS DISTINCT FROM 'array'
                THEN
                    RETURN false;
                END IF;
                FOR item IN SELECT value FROM jsonb_array_elements(candidate -> 'items')
                LOOP
                    IF item ->> 'type' = 'tuple'
                       OR NOT evidence.is_valid_tagged_value(item)
                    THEN
                        RETURN false;
                    END IF;
                END LOOP;
                RETURN true;
            END IF;

            IF key_count <> 2 OR NOT candidate ?& ARRAY['type', 'value'] THEN
                RETURN false;
            END IF;
            value_type := jsonb_typeof(candidate -> 'value');
            value_text := candidate ->> 'value';

            IF tag = 'null' THEN
                RETURN value_type = 'null';
            ELSIF tag = 'string' THEN
                RETURN value_type = 'string';
            ELSIF tag = 'integer' THEN
                RETURN value_type = 'number'
                   AND (candidate -> 'value')::text ~ '^(0|-?[1-9][0-9]*)$';
            ELSIF tag = 'decimal' THEN
                RETURN value_type = 'string'
                   AND value_text ~ '^(0|-?[1-9][0-9]*|-?(0|[1-9][0-9]*)\.[0-9]*[1-9])$';
            ELSIF tag = 'boolean' THEN
                RETURN value_type = 'boolean';
            ELSIF tag = 'date' THEN
                IF value_type <> 'string'
                   OR value_text !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
                THEN
                    RETURN false;
                END IF;
                PERFORM value_text::date;
                RETURN true;
            ELSIF tag = 'datetime' THEN
                IF value_type <> 'string'
                   OR value_text !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]{6})?Z$'
                   OR value_text ~ '\.000000Z$'
                THEN
                    RETURN false;
                END IF;
                PERFORM value_text::timestamptz;
                RETURN true;
            END IF;
            RETURN false;
        EXCEPTION
            WHEN datetime_field_overflow OR invalid_datetime_format THEN
                RETURN false;
        END
        $function$

CREATE OR REPLACE FUNCTION evidence.validate_calculation_aggregate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'evidence', 'pg_temp'
AS $function$
        DECLARE
            stored_type text;
            stored_tie_break text;
            evidence_input_count integer;
            dependency_count integer;
            population_count integer;
            population_filter_count integer;
        BEGIN
            SELECT calculation_type, tie_break_rule
              INTO stored_type, stored_tie_break
              FROM evidence.calculation_record
             WHERE run_id = NEW.run_id
               AND calculation_id = NEW.calculation_id;
            IF stored_type IS NULL THEN
                RETURN NEW;
            END IF;

            SELECT count(*) INTO evidence_input_count
              FROM evidence.calculation_evidence_input
             WHERE run_id = NEW.run_id
               AND calculation_id = NEW.calculation_id;
            SELECT count(*) INTO dependency_count
              FROM evidence.calculation_dependency
             WHERE run_id = NEW.run_id
               AND calculation_id = NEW.calculation_id;
            SELECT count(*) INTO population_count
              FROM evidence.calculation_population
             WHERE run_id = NEW.run_id
               AND calculation_id = NEW.calculation_id;
            SELECT count(*) INTO population_filter_count
              FROM evidence.calculation_population_filter
             WHERE run_id = NEW.run_id
               AND calculation_id = NEW.calculation_id;

            IF evidence_input_count + dependency_count = 0 THEN
                RAISE EXCEPTION 'CALCULATION_INPUT_REQUIRED'
                    USING ERRCODE = '23514';
            END IF;
            IF stored_type IN ('ranking', 'aggregation')
               AND population_count <> 1 THEN
                RAISE EXCEPTION 'CALCULATION_POPULATION_REQUIRED'
                    USING ERRCODE = '23514';
            END IF;
            IF stored_type = 'ranking'
               AND (population_filter_count = 0 OR stored_tie_break IS NULL) THEN
                RAISE EXCEPTION 'RANKING_METADATA_INCOMPLETE'
                    USING ERRCODE = '23514';
            END IF;
            RETURN NEW;
        END
        $function$

CREATE OR REPLACE FUNCTION evidence.validate_claim_aggregate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'evidence', 'pg_temp'
AS $function$
        DECLARE
            stored_type text;
            has_target boolean;
            qualifier_count integer;
            support_count integer;
        BEGIN
            SELECT claim_type, num_nonnulls(object_id, value) = 1
              INTO stored_type, has_target
              FROM evidence.atomic_claim
             WHERE run_id = NEW.run_id
               AND claim_id = NEW.claim_id;
            IF stored_type IS NULL THEN
                RETURN NEW;
            END IF;
            SELECT count(*) INTO qualifier_count
              FROM evidence.claim_qualifier
             WHERE run_id = NEW.run_id AND claim_id = NEW.claim_id;
            SELECT count(*) INTO support_count
              FROM evidence.claim_support
             WHERE run_id = NEW.run_id AND claim_id = NEW.claim_id;

            IF support_count = 0 THEN
                RAISE EXCEPTION 'CLAIM_SUPPORT_REQUIRED'
                    USING ERRCODE = '23514';
            END IF;
            IF NOT has_target
               AND (stored_type NOT IN ('data_limitation','policy_boundary')
                    OR qualifier_count = 0) THEN
                RAISE EXCEPTION 'QUALIFIER_ONLY_CLAIM_INVALID'
                    USING ERRCODE = '23514';
            END IF;
            RETURN NEW;
        END
        $function$

CREATE OR REPLACE FUNCTION evidence.validate_cutoff_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'evidence', 'operations', 'pg_temp'
AS $function$
        DECLARE
            dataset_cutoff date;
            has_after_cutoff boolean;
        BEGIN
            SELECT dataset.cutoff_date
              INTO dataset_cutoff
              FROM operations.dataset_version AS dataset
             WHERE dataset.dataset_version = NEW.dataset_version
             FOR KEY SHARE;

            IF dataset_cutoff IS NULL THEN
                RETURN NEW;
            END IF;
            has_after_cutoff :=
                COALESCE(NEW.applicable_date > dataset_cutoff, false)
                OR COALESCE(
                    (NEW.published_at AT TIME ZONE 'UTC')::date > dataset_cutoff,
                    false
                )
                OR COALESCE(
                    (NEW.available_at AT TIME ZONE 'UTC')::date > dataset_cutoff,
                    false
                )
                OR COALESCE(NEW.vintage_date > dataset_cutoff, false);

            IF has_after_cutoff AND NEW.cutoff_status <> 'after_cutoff' THEN
                RAISE EXCEPTION 'EVIDENCE_AFTER_CUTOFF_STATUS_REQUIRED'
                    USING ERRCODE = '23514';
            ELSIF NOT has_after_cutoff AND NEW.cutoff_status = 'after_cutoff' THEN
                RAISE EXCEPTION 'EVIDENCE_AFTER_CUTOFF_STATUS_INVALID'
                    USING ERRCODE = '23514';
            END IF;
            RETURN NEW;
        END
        $function$

CREATE OR REPLACE FUNCTION operations.activate_dataset(p_dataset_version text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'operations', 'pg_temp'
AS $function$
        DECLARE
            prior_active_version text;
            target_status text;
            readiness_count integer;
        BEGIN
            PERFORM pg_catalog.pg_advisory_xact_lock(
                pg_catalog.hashtextextended('operations.activate_dataset', 0)
            );
            SELECT active.dataset_version
              INTO prior_active_version
              FROM operations.active_dataset AS active
             WHERE active.singleton
             FOR UPDATE;

            SELECT dataset.status
              INTO target_status
              FROM operations.dataset_version AS dataset
             WHERE dataset.dataset_version = p_dataset_version
             FOR UPDATE;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'DATASET_NOT_FOUND'
                    USING ERRCODE = 'P0002';
            END IF;
            IF target_status IS DISTINCT FROM 'validated' THEN
                RAISE EXCEPTION 'DATASET_NOT_VALIDATED'
                    USING ERRCODE = '55000';
            END IF;

            SELECT count(*)
              INTO readiness_count
              FROM operations.dataset_readiness AS readiness
             WHERE readiness.dataset_version = p_dataset_version
               AND readiness.component IN (
                   'postgres', 'graph', 'vector', 'evidence'
               );
            IF readiness_count <> 4 THEN
                RAISE EXCEPTION 'DATASET_READINESS_INCOMPLETE'
                    USING ERRCODE = '23514';
            END IF;

            IF prior_active_version IS NOT NULL AND
               prior_active_version <> p_dataset_version THEN
                UPDATE operations.dataset_version AS dataset
                   SET status = 'retired'
                 WHERE dataset.dataset_version = prior_active_version
                   AND dataset.status = 'active';
            END IF;
            UPDATE operations.dataset_version
               SET status = 'active',
                   activated_at = pg_catalog.clock_timestamp()
             WHERE dataset_version = p_dataset_version
               AND status = 'validated';
            IF NOT FOUND THEN
                RAISE EXCEPTION 'DATASET_ACTIVATION_CONFLICT'
                    USING ERRCODE = '40001';
            END IF;
            UPDATE operations.active_dataset
               SET dataset_version = p_dataset_version,
                   activated_at = pg_catalog.clock_timestamp()
             WHERE singleton;
            RETURN p_dataset_version;
        END
        $function$

CREATE OR REPLACE FUNCTION operations.derive_request_artifact()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'operations', 'pg_temp'
AS $function$
        BEGIN
            NEW.payload_jsonb := NEW.canonical_payload::jsonb;
            IF pg_catalog.jsonb_typeof(NEW.payload_jsonb) IS DISTINCT FROM 'object'
            THEN
                RAISE EXCEPTION 'ARTIFACT_PAYLOAD_INVALID'
                    USING ERRCODE = '22023';
            END IF;

            NEW.payload_hash := pg_catalog.encode(
                public.digest(NEW.canonical_payload, 'sha256'), 'hex'
            );
            NEW.schema_version := NEW.payload_jsonb ->> 'schema_version';
            NEW.request_key := NEW.payload_jsonb ->> 'request_key';
            NEW.run_id := NEW.payload_jsonb ->> 'run_id';
            NEW.dataset_version := NEW.payload_jsonb ->> 'dataset_version';
            NEW.cutoff_date := (NEW.payload_jsonb ->> 'cutoff_date')::date;
            NEW.producer := NEW.payload_jsonb ->> 'producer';
            NEW.created_at := (NEW.payload_jsonb ->> 'created_at')::timestamptz;
            NEW.contract_object_id := CASE NEW.artifact_type
                WHEN 'execution_graph' THEN NEW.payload_jsonb ->> 'graph_id'
                WHEN 'tool_result' THEN NEW.payload_jsonb ->> 'task_id'
                WHEN 'evidence_bundle' THEN NEW.payload_jsonb ->> 'bundle_id'
                WHEN 'verification_report'
                    THEN NEW.payload_jsonb ->> 'verification_report_id'
                ELSE NULL
            END;

            IF NEW.schema_version IS NULL OR NEW.request_key IS NULL
               OR NEW.run_id IS NULL OR NEW.dataset_version IS NULL
               OR NEW.cutoff_date IS NULL OR NEW.producer IS NULL
               OR NEW.created_at IS NULL
            THEN
                RAISE EXCEPTION 'ARTIFACT_METADATA_INVALID'
                    USING ERRCODE = '22023';
            END IF;
            RETURN NEW;
        EXCEPTION
            WHEN invalid_text_representation OR datetime_field_overflow
                 OR invalid_datetime_format THEN
                RAISE EXCEPTION 'ARTIFACT_PAYLOAD_INVALID'
                    USING ERRCODE = '22023';
        END
        $function$

CREATE OR REPLACE FUNCTION operations.finish_dataset_validation(p_validation_run_id text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'operations', 'pg_temp'
AS $function$
        DECLARE
            validation_record operations.dataset_validation_run%ROWTYPE;
            dataset_record operations.dataset_version%ROWTYPE;
            next_status text;
        BEGIN
            SELECT validation.*
              INTO validation_record
              FROM operations.dataset_validation_run AS validation
             WHERE validation.validation_run_id = p_validation_run_id
             FOR UPDATE;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'VALIDATION_RUN_NOT_FOUND'
                    USING ERRCODE = 'P0002';
            END IF;

            SELECT dataset.*
              INTO dataset_record
              FROM operations.dataset_version AS dataset
             WHERE dataset.dataset_version = validation_record.dataset_version
             FOR UPDATE;
            IF dataset_record.status IS DISTINCT FROM 'building' THEN
                RAISE EXCEPTION 'DATASET_NOT_BUILDING'
                    USING ERRCODE = '55000';
            END IF;
            IF dataset_record.manifest_hash IS DISTINCT FROM
               validation_record.dataset_manifest_hash THEN
                RAISE EXCEPTION 'DATASET_MANIFEST_MISMATCH'
                    USING ERRCODE = '23514';
            END IF;

            next_status := CASE validation_record.status
                WHEN 'pass' THEN 'validated'
                ELSE 'failed'
            END;
            UPDATE operations.dataset_version
               SET status = next_status,
                   validated_at = validation_record.finished_at
             WHERE dataset_version = validation_record.dataset_version;
            RETURN next_status;
        END
        $function$

CREATE OR REPLACE FUNCTION operations.reject_nonbuilding_dataset_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'operations', 'pg_temp'
AS $function$
        DECLARE
            target_dataset_version text;
            target_status text;
        BEGIN
            IF TG_OP = 'UPDATE' THEN
                IF OLD.dataset_version IS DISTINCT FROM NEW.dataset_version THEN
                    RAISE EXCEPTION 'DATASET_REASSIGNMENT_FORBIDDEN'
                        USING ERRCODE = '55000';
                END IF;
                target_dataset_version := NEW.dataset_version;
            ELSIF TG_OP = 'DELETE' THEN
                target_dataset_version := OLD.dataset_version;
            ELSE
                target_dataset_version := NEW.dataset_version;
            END IF;
            SELECT dataset.status
              INTO target_status
              FROM operations.dataset_version AS dataset
             WHERE dataset.dataset_version = target_dataset_version
             FOR SHARE;
            IF target_status IS DISTINCT FROM 'building' THEN
                RAISE EXCEPTION 'DATASET_NOT_BUILDING'
                    USING ERRCODE = '55000';
            END IF;
            RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
        END
        $function$
